// Package media holds the shared domain types exchanged between the
// manifest, transport, timeline, quality and render subsystems.
//
// All time values are expressed on one integer media clock: ClockRate
// ticks per second. No float arithmetic is ever used for timestamps,
// which prevents accumulation drift across segment boundaries.
package media

// ClockRate is the ticks-per-second rate of the unified media clock.
// 90 kHz divides every common track timebase (24/25/30 fps, 48 kHz ...).
const ClockRate int64 = 90000

// TrackKind distinguishes the media kinds generated by the fixtures.
type TrackKind string

const (
	TrackVideo TrackKind = "video"
	TrackAudio TrackKind = "audio"
)

// TrackSpec describes one track as declared by a manifest.
type TrackSpec struct {
	ID                 uint32
	Name               string
	Kind               TrackKind
	Width              uint16
	Height             uint16
	TimebaseNum        uint32 // track timebase as a rational fps/rate
	TimebaseDen        uint32
	TargetBitrateKbps  int
	BandwidthKbps      int // simulated delivered bandwidth for this track
}

// Frame is one decodable (or corrupt) sample on the unified clock.
type Frame struct {
	TrackID     uint32
	SegmentSeq  uint32
	Index       uint32 // frame index inside its segment
	PTS         int64  // presentation timestamp, unified-clock ticks
	Duration    int64  // frame duration in unified-clock ticks
	Width       uint16
	Height      uint16
	Luma        uint8
	PayloadSize int  // ARCH frame payload bytes actually received
	Corrupt     bool // truncated / undecodable payload
}

// Segment is the reassembled, timeline-aligned result for one manifest
// segment reference of one track.
type Segment struct {
	TrackID       uint32
	Seq           uint32
	StartTicks    int64
	DurationTicks int64
	MediaBytes    int // effective media bytes; duplicate packets count once
	Frames        []Frame
	LostPackets   int
	Truncated     bool
}

// Lost returns whether the segment carries a burst-loss gap.
func (s *Segment) Lost() bool { return s.LostPackets > 0 }
